const input = $input.first().json;
const body = input.body || input;
const validActions = [
  'save_account_definition',
  'save_account',
  'save_persona_intent',
  'scrape_lookalike_profile',
  'generate_strategy_and_launch',
  'get_industry_name',
  'get_scrape_status',
  'get_results',
  'reveal_email'
];
const errors = [];

if (!body.action || !validActions.includes(body.action)) {
  errors.push(`Invalid action: ${body.action || 'none'}`);
}

if (body.action !== 'get_industry_name' && !body.session_id) {
  errors.push('Missing required session_id');
}

if (body.account_data) {
  body.profile_name = body.account_data.name;
  body.target_industry = body.account_data.industries;
  body.company_size = body.account_data.size;
  body.company_location = body.account_data.location;
  body.hiring_intensity = body.account_data.hiring_intensity;
  const requestedTarget = parseInt(body.account_data.target_results_count) || 50;
  body.target_results_count = Math.max(20, Math.min(requestedTarget, 100));
}

if (!body.target_results_count) {
  body.target_results_count = 50;
}

if (body.action === 'save_account') {
  body.action = 'save_account_definition';
}

if (body.action === 'save_persona_intent') {
  body.persona_description = body.search_query || body.persona_description;
  if (!body.persona_description) errors.push('Missing search_query text');
}

if (body.action === 'scrape_lookalike_profile') {
  if (!body.linkedin_url) errors.push('LinkedIn URL is required for scraping');
}

if (body.action === 'reveal_email') {
  if (!body.linkedin_url) errors.push('linkedin_url is required for email reveal');
  if (!body.profile_id) errors.push('profile_id is required for email reveal');
}

if (errors.length > 0) {
  return [{ 
    json: { 
      success: false, 
      error_code: 'VALIDATION_FAILED', 
      errors: errors 
    } 
  }];
}

return [{ json: { ...body, validated: true } }];

const input = $input.first().json;
// Changed 'Webhook Trigger1' to 'Webhook Trigger' to match your canvas
const webhookBody = $('Webhook Trigger').first().json.body;

return [{
  json: {
    success: true,
    message: 'Account definition saved successfully',
    data: {
      session_id: webhookBody.session_id,
      step: 1,
      next_step: 'save_persona_intent',
      saved: {
        profile_name: webhookBody.profile_name,
        industry_names: webhookBody.industry_names,
        industry_ids: webhookBody.industry_ids,
        company_size: webhookBody.company_size,
        company_location: webhookBody.company_location,
        hiring_intensity: webhookBody.hiring_intensity
      }
    },
    errors: []
  }
}];

const input = $json;

// Extract URL - check both possible field names from frontend
const url = input.linkedin_url || input.url;

if (!url) {
  throw new Error('No URL found in the input data. Check field names.');
}

// Extract username using the regex
const match = url.match(/linkedin\.com\/in\/([a-zA-Z0-9_-]+)/);
const username = match ? match[1] : null;

if (!username) {
  throw new Error(`Could not extract username from LinkedIn URL: ${url}`);
}

return [{
  json: {
    session_id: input.session_id,
    linkedin_url: url,
    username: username,
    apify_input: {
      profileUrls: [url],
      profileScraperMode: 'Full',
      maxItems: 1
    }
  }
}];

const items = $input.all();
const sessionId = $('Prepare Apify Scrape').first().json.session_id;
const linkedinUrl = $('Prepare Apify Scrape').first().json.linkedin_url;

// Handle empty or error results
if (!items || items.length === 0 || items[0].json.error) {
  const error = new Error('Profile scrape failed');
  error.description = JSON.stringify({
    success: false,
    error_code: 'PROFILE_SCRAPE_FAILED',
    message: 'Failed to scrape LinkedIn profile. Please check the URL and try again.',
    data: { linkedin_url: linkedinUrl, session_id: sessionId },
    errors: [{ stage: 'profile_scrape', error: 'Apify returned no results or error' }]
  });
  throw error;
}

const profile = items[0].json;

// 1. Basic Info & Professional Branding
const name = profile.fullName || `${profile.firstName || ''} ${profile.lastName || ''}`.trim() || 'Unknown';
const headline = profile.headline || '';
const photoUrl = profile.profilePicHighQuality || profile.profilePic || '';
const location = profile.addressWithoutCountry || profile.jobLocation || profile.addressWithCountry || '';

// 2. Work History Mapping
const workHistory = (profile.experiences || []).map(exp => ({
  company: exp.companyName || '',
  title: exp.title || '',
  location: exp.jobLocation || '',
  industry: exp.companyIndustry || '',
  description: exp.jobDescription || '',
  start_date: exp.jobStartedOn || '',
  end_date: exp.jobEndedOn || 'Present',
  is_current: exp.jobStillWorking === true
})).filter(w => w.company || w.title);

// 3. Experience & Seniority Calculations
const totalYears = profile.totalExperienceYears || 0;
const currentTitle = profile.jobTitle || (workHistory.find(w => w.is_current)?.title) || '';
const currentCompany = profile.companyName || (workHistory.find(w => w.is_current)?.company) || '';

let seniorityLevel = 'Junior';
const titleLower = currentTitle.toLowerCase();
if (titleLower.includes('founder') || titleLower.includes('ceo') || titleLower.includes('director') || titleLower.includes('vp') || totalYears >= 12) {
  seniorityLevel = 'Executive';
} else if (titleLower.includes('senior') || titleLower.includes('lead') || titleLower.includes('principal') || totalYears >= 8) {
  seniorityLevel = 'Senior';
} else if (titleLower.includes('manager') || totalYears >= 4) {
  seniorityLevel = 'Mid';
}

// 4. Past Companies & Industry Focus
const pastCompaniesList = [...new Set(workHistory.filter(w => !w.is_current).map(w => w.company))].slice(0, 5);
const primaryIndustry = workHistory[0]?.industry || 'Professional Services';

// 5. Insights for Recruiter Preview
const experienceSummary = `${seniorityLevel} level professional with ${Math.round(totalYears)} years of experience, primarily in ${primaryIndustry}. Career trajectory includes key roles at ${pastCompaniesList.join(', ')}.`.trim();

// 6. Skills & Education
const topSkills = (profile.skills || []).map(s => s.title).filter(Boolean);
const education = (profile.educations || []).map(edu => ({
  school: edu.title || '',
  degree: edu.subtitle || '',
  display: `${edu.subtitle || 'Studies'} at ${edu.title || 'University'}`
})).filter(e => e.school);

// 7. Final Payload Construction
const richProfile = {
  name,
  photo_url: photoUrl,
  headline,
  current_title: currentTitle,
  current_company: currentCompany,
  location,
  linkedin_url: linkedinUrl,

  // Professional DNA (Enriched for Recruiter)
  top_skills: topSkills.slice(0, 10),
  skills_count: topSkills.length,
  total_years_experience: Math.round(totalYears),
  seniority_level: seniorityLevel,
  experience_summary: experienceSummary, // <-- New insightful field

  // History
  education,
  education_summary: education.length > 0 ? education[0].display : 'Not specified',
  work_history: workHistory,
  past_companies: pastCompaniesList,

  // Metadata
  profile_completeness: 100,
  scraped_at: new Date().toISOString()
};

return [{
  json: {
    success: true,
    session_id: sessionId,
    profile: richProfile
  }
}];

// LAYER 8: AUDITABILITY - Complete Response with Validation Metadata
const webhookBody = $('Webhook Trigger').first().json.body || {};
const profileData = $('Extract Profile Data').first().json.profile || {};
const strategyData = $('Validate Job Titles').first().json;
const context = $('Prepare Strategy Context').first().json;

return [{
  json: {
    success: true,
    message: 'Profile scraped and strategy generated successfully',
    data: {
      session_id: webhookBody.session_id,

      // Enriched Profile Data
      profile: {
        name: profileData.name || '',
        photo_url: profileData.photo_url || '',
        headline: profileData.headline || '',
        current_title: profileData.current_title || '',
        current_company: profileData.current_company || '',
        location: profileData.location || '',
        seniority: profileData.seniority_level || '',
        years_experience: profileData.total_years_experience || 0,
        top_skills: profileData.top_skills || [],
        education: profileData.education || [],
        work_history: (profileData.work_history || []).slice(0, 3),
        focus_areas: [profileData.work_history?.[0]?.industry || '']
      },

      // LAYER 8: AUDITABILITY - Include role classification
      role_family: strategyData.role_family,

      // AI Generated Strategy
      generated_strategy: strategyData.generated_strategy || '',
      search_logic_dna: strategyData.search_logic_dna || '',

      // LAYER 8: AUDITABILITY - Include validation signals
      mandatory_signals: strategyData.mandatory_signals,
      excluded_signals: strategyData.excluded,

      // Validation metadata from title hardening
      validation_metadata: strategyData.validation_metadata,

      // Firmographic Constraints from context
      firmographic_constraints: {
        industries: context.industries || [],
        locations: context.locations || [],
        company_sizes: context.company_size || [],
        hiring_intensity: context.hiring_intensity || ''
      },

      // Technical Apify Parameters (validated)
      technical_execution: strategyData.apify_params || {}
    }
  }
}];

// Aggregate error information with specific error codes
const items = $input.all();
const firstItem = items[0]?.json || {};

// Determine error code and details
let errorCode = 'UNKNOWN_ERROR';
let errorMessage = 'Unknown error occurred';
let details = '';
let stage = 'unknown';

// Check if this is a validation error with error_code already set
if (firstItem.error_code) {
  errorCode = firstItem.error_code;
  errorMessage = firstItem.message || 'Processing error';
  details = JSON.stringify(firstItem.errors || []);
  stage = 'validation';
} 
// Check for structured error in description (from thrown errors)
else if (firstItem.description) {
  try {
    const parsed = JSON.parse(firstItem.description);
    errorCode = parsed.error_code || 'PROCESSING_ERROR';
    errorMessage = parsed.message || 'Processing error';
    details = JSON.stringify(parsed.errors || []);
    stage = parsed.errors?.[0]?.stage || 'processing';
  } catch (e) {
    errorMessage = firstItem.description;
    stage = 'processing';
  }
}
// Standard error handling
else {
  errorMessage = firstItem.message || firstItem.error || 'Processing error';
  details = firstItem.stack || '';

  // Determine error code based on error message
  if (errorMessage.includes('LinkedIn') || errorMessage.includes('URL')) {
    errorCode = 'INVALID_URL';
    stage = 'validation';
  } else if (errorMessage.includes('scrape') || errorMessage.includes('Apify')) {
    errorCode = 'PROFILE_SCRAPE_FAILED';
    stage = 'profile_scrape';
  } else if (errorMessage.includes('required') || errorMessage.includes('Missing')) {
    errorCode = 'MISSING_FIELDS';
    stage = 'validation';
  } else if (errorMessage.includes('database') || errorMessage.includes('Supabase')) {
    errorCode = 'DATABASE_ERROR';
    stage = 'database';
  } else if (errorMessage.includes('AI') || errorMessage.includes('Claude') || errorMessage.includes('OpenAI')) {
    errorCode = 'AI_GENERATION_ERROR';
    stage = 'ai_generation';
  } else {
    errorCode = 'PROCESSING_ERROR';
    stage = 'processing';
  }
}

return [{
  json: {
    success: false,
    error_code: errorCode,
    message: errorMessage,
    data: null,
    errors: [{
      stage: stage,
      error: errorMessage,
      details: details,
      timestamp: new Date().toISOString()
    }]
  }
}];

const input = $input.first().json;
// Reference updated to 'Webhook Trigger' to match your actual node name
const webhookBody = $('Webhook Trigger').first().json.body;

return [{
  json: {
    success: true,
    message: 'Persona intent saved successfully',
    data: {
      session_id: webhookBody.session_id,
      step: 2,
      next_step: 'scrape_lookalike_profile',
      saved: {
        persona_description: webhookBody.persona_description,
        character_count: webhookBody.persona_description?.length || 0
      }
    },
    errors: []
  }
}];

// LAYER 1-2: Parse AI Output with Tier-Specific Signal Extraction
const aiNode = $('AI Strategy Generation').first();
const aiText = aiNode.json.text || aiNode.json.output || '';
const context = $('Prepare Strategy Context').first().json;

// Default structure with SAFE DEFAULTS (Layer 7)
let parsed = {
  role_family: 'other',
  niche_specialization: '',
  mandatory_signals: {
    job_titles: [],
    keywords: [],
    industries: []
  },
  supportive_signals: {
    skills: [],
    past_companies: [],
    certifications: []
  },
  excluded: {
    role_families: [],
    industries: ['Arts', 'Music', 'Entertainment', 'Non-profit', 'Religious', 'Wildlife', 'Conservation'],
    keywords: []
  },
  generated_strategy: '',
  search_logic_dna: '',
  tier_1_params: null,
  tier_2_params: null,
  tier_3_params: null
};

try {
  // Parse JSON from AI response
  const jsonStr = aiText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  const aiParsed = JSON.parse(jsonStr);

  // Extract role_family and niche
  parsed.role_family = aiParsed.role_family || 'other';
  parsed.niche_specialization = aiParsed.niche_specialization || '';

  // Extract mandatory_signals
  if (aiParsed.mandatory_signals) {
    parsed.mandatory_signals = {
      job_titles: aiParsed.mandatory_signals.job_titles || [],
      keywords: aiParsed.mandatory_signals.keywords || [],
      industries: aiParsed.mandatory_signals.industries || []
    };
  }

  // Extract supportive_signals
  if (aiParsed.supportive_signals) {
    parsed.supportive_signals = {
      skills: aiParsed.supportive_signals.skills || [],
      past_companies: aiParsed.supportive_signals.past_companies || [],
      certifications: aiParsed.supportive_signals.certifications || []
    };
  }

  // Extract excluded signals
  if (aiParsed.excluded) {
    parsed.excluded = {
      role_families: aiParsed.excluded.role_families || [],
      industries: [...new Set([...(aiParsed.excluded.industries || []), 'Arts', 'Music', 'Entertainment', 'Non-profit', 'Religious', 'Wildlife', 'Conservation'])],
      keywords: aiParsed.excluded.keywords || []
    };
  }

  // Extract strategy explanations
  parsed.generated_strategy = aiParsed.generated_strategy || '';
  parsed.search_logic_dna = aiParsed.search_logic_dna || '';

  // Extract tier-specific params
  parsed.tier_1_params = aiParsed.tier_1_params || null;
  parsed.tier_2_params = aiParsed.tier_2_params || null;
  parsed.tier_3_params = aiParsed.tier_3_params || null;

} catch (error) {
  console.error('Failed to parse AI output:', error.message);
}

// LAYER 7: SAFE DEFAULTS - Validate tier params exist
if (!parsed.tier_1_params) {
  console.warn('No tier_1_params from AI, generating fallback');
  const fallbackKeywords = parsed.mandatory_signals.keywords.slice(0, 5).join(' ');
  parsed.tier_1_params = {
    searchQuery: fallbackKeywords || `${parsed.role_family} professional`,
    currentJobTitles: [],
    skills: parsed.supportive_signals.skills.slice(0, 4),
    industryIds: context.industry_ids || [],
    locations: context.locations || [],
    seniorityLevelIds: [],
    yearsOfExperienceIds: [],
    profileLanguages: ['English'],
    profileScraperMode: 'Full',
    maxItems: 100
  };
}

return [{
  json: {
    role_family: parsed.role_family,
    niche_specialization: parsed.niche_specialization,
    mandatory_signals: parsed.mandatory_signals,
    supportive_signals: parsed.supportive_signals,
    excluded: parsed.excluded,
    generated_strategy: parsed.generated_strategy,
    search_logic_dna: parsed.search_logic_dna,
    tier_1_params: parsed.tier_1_params,
    tier_2_params: parsed.tier_2_params,
    tier_3_params: parsed.tier_3_params,
    // Keep legacy apify_params for backward compatibility (use tier_1)
    apify_params: parsed.tier_1_params
  }
}];

// LAYER 3-4: Title Hardening & Industry/Skill Gating
const input = $('Parse AI Output').first().json;
const apifyParams = { ...input.apify_params };
const roleFamily = input.role_family;
const excluded = input.excluded || {};

// ===== LAYER 3: TITLE HARDENING =====
const GENERIC_TITLES = ['Founder', 'Director', 'Manager', 'Head', 'Lead', 'Owner', 'Partner', 'Principal', 'President', 'Chairman'];

const ROLE_FAMILY_KEYWORDS = {
  'recruiting': ['recruit', 'talent', 'staffing', 'hr', 'human resources', 'sourcer', 'headhunt', 'acquisition'],
  'engineering': ['engineer', 'developer', 'architect', 'swe', 'devops', 'sre', 'programmer', 'technical'],
  'sales': ['sales', 'account', 'business development', 'revenue', 'bdr', 'sdr', 'ae', 'commercial'],
  'marketing': ['marketing', 'growth', 'brand', 'content', 'demand gen', 'digital', 'communications'],
  'finance': ['finance', 'accounting', 'controller', 'analyst', 'fp&a', 'treasury', 'audit', 'cfo'],
  'product': ['product', 'pm', 'product manager', 'product owner', 'roadmap'],
  'data': ['data', 'analytics', 'scientist', 'ml', 'machine learning', 'ai', 'bi', 'intelligence'],
  'design': ['design', 'ux', 'ui', 'creative', 'visual', 'graphic', 'user experience'],
  'operations': ['operations', 'ops', 'supply chain', 'logistics', 'procurement', 'facilities'],
  'legal': ['legal', 'counsel', 'attorney', 'lawyer', 'compliance', 'regulatory'],
  'hr': ['hr', 'human resources', 'people', 'culture', 'compensation', 'benefits', 'learning'],
  'executive': ['ceo', 'cto', 'cfo', 'coo', 'cmo', 'cpo', 'chief', 'vp', 'vice president', 'evp', 'svp'],
  'consulting': ['consultant', 'advisor', 'strategist', 'transformation'],
  'healthcare': ['nurse', 'doctor', 'physician', 'clinical', 'medical', 'healthcare', 'patient']
};

const validateTitle = (title, roleFamily) => {
  if (!title || title.trim() === '') return { valid: false, reason: 'Empty title' };
  const titleLower = title.toLowerCase().trim();
  const isOnlyGeneric = GENERIC_TITLES.some(g => titleLower === g.toLowerCase());
  if (isOnlyGeneric) return { valid: false, reason: `Generic title: ${title}` };
  const keywords = ROLE_FAMILY_KEYWORDS[roleFamily] || [];
  if (keywords.length > 0) {
    const hasRoleKeyword = keywords.some(kw => titleLower.includes(kw.toLowerCase()));
    if (!hasRoleKeyword) return { valid: false, reason: `No role match: ${title}` };
  }
  const excludedFamilies = excluded.role_families || [];
  for (const exFamily of excludedFamilies) {
    const exKeywords = ROLE_FAMILY_KEYWORDS[exFamily] || [];
    if (exKeywords.some(kw => titleLower.includes(kw.toLowerCase()))) {
      return { valid: false, reason: `Excluded family: ${exFamily}` };
    }
  }
  return { valid: true, reason: 'Passed' };
};

const titleValidation = apifyParams.currentJobTitles.map(title => ({ title, ...validateTitle(title, roleFamily) }));
const validTitles = titleValidation.filter(t => t.valid).map(t => t.title);
const rejectedTitles = titleValidation.filter(t => !t.valid);

if (validTitles.length === 0) {
  throw new Error(JSON.stringify({
    success: false,
    error_code: 'TITLE_VALIDATION_FAILED',
    message: `No valid job titles for role family: ${roleFamily}`,
    data: { rejected_titles: rejectedTitles }
  }));
}
apifyParams.currentJobTitles = validTitles;

// LAYER 4: SKILL GATING
const EXCLUDED_SKILLS = ['music', 'art', 'painting', 'wildlife', 'conservation', 'teaching', 'academic research', 'nonprofit', 'charity', 'volunteering', 'ministry', 'pottery', 'theater', 'acting', 'singing', 'dancing', 'religious', 'spiritual', 'meditation', 'yoga instructor'];
apifyParams.skills = (apifyParams.skills || []).filter(skill => {
  if (!skill) return false;
  const skillLower = skill.toLowerCase();
  return !EXCLUDED_SKILLS.some(ex => skillLower.includes(ex)) && !(excluded.keywords || []).some(kw => skillLower.includes(kw.toLowerCase()));
});

// LAYER 4: INDUSTRY GATING
const EXCLUDED_INDUSTRY_IDS = ['39', '40', '37', '71', '72', '94'];
apifyParams.industryIds = (apifyParams.industryIds || []).filter(id => !EXCLUDED_INDUSTRY_IDS.includes(String(id)));

// VALIDATE SEARCH QUERY
if (!apifyParams.searchQuery || apifyParams.searchQuery.trim().length < 5) {
  apifyParams.searchQuery = (input.mandatory_signals?.keywords || []).slice(0, 5).join(' ') || `${roleFamily} professional`;
}

return [{
  json: {
    ...input,
    apify_params: apifyParams,
    validation_metadata: {
      valid_titles: validTitles.length,
      rejected_titles: rejectedTitles
    }
  }
}];

// TIER 1: HIGH PRECISION - Use AI-generated tier-specific params
const session = $('Retrieve Session Data').first().json;
const strategyData = $('Validate Job Titles').first().json;

const targetCount = parseInt(session.target_results_count) || 50;
const tier1Threshold = Math.ceil(targetCount * 0.8);
const tier2Threshold = targetCount;

// Use AI-generated Tier 1 parameters
const tier1Params = strategyData.tier_1_params || strategyData.apify_params;

if (!tier1Params || !tier1Params.searchQuery) {
  throw new Error('No tier_1_params from AI strategy generation');
}

// Smart maxItems: overfetch by 50% for post-filtering, cap at 150
const maxItems = Math.min(Math.ceil(targetCount * 1.5), 150);
tier1Params.maxItems = maxItems;

// Validation
const issues = [];
if (!tier1Params.searchQuery || tier1Params.searchQuery.length < 5) issues.push('searchQuery too short');
if (tier1Params.searchQuery.includes('--')) issues.push('searchQuery has double-dash');

if (issues.length > 0) {
  console.error('VALIDATION ISSUES:', issues);
  throw new Error('Invalid Tier 1 input: ' + issues.join('; '));
}

// Logging
console.log('━━━━━━━━━━━━━━━━━━━━━━━━');
console.log('BUILD TIER 1 INPUT (AI-GENERATED)');
console.log('━━━━━━━━━━━━━━━━━━━━━━━━');
console.log('Session ID:', session.session_id);
console.log('Profile:', session.profile_name);
console.log('Target count:', targetCount);
console.log('Tier 1 threshold (80%):', tier1Threshold);
console.log('maxItems:', maxItems);
console.log('');
console.log('AI-GENERATED TIER 1 PARAMS:');
console.log('  searchQuery:', tier1Params.searchQuery);
console.log('  skills:', tier1Params.skills);
console.log('  industryIds:', tier1Params.industryIds);
console.log('  locations:', tier1Params.locations);
console.log('  seniorityLevelIds:', tier1Params.seniorityLevelIds);
console.log('  yearsOfExperienceIds:', tier1Params.yearsOfExperienceIds);
console.log('━━━━━━━━━━━━━━━━━━━━━━━━');

return [{ json: {
  tier: 1,
  session_id: session.session_id,
  profile_name: session.profile_name,
  role_family: strategyData.role_family,
  apify_input: tier1Params,
  enforced_mandatory_signals: strategyData.mandatory_signals,
  enforced_excluded_signals: strategyData.excluded,
  lookalike_anchor: strategyData.lookalike_anchor || {},
  firmographic_constraints: strategyData.firmographic_constraints || {},
  target_count: targetCount,
  tier_config: { tier1_threshold: tier1Threshold, tier2_threshold: tier2Threshold, target_count: targetCount }
}}];

// CHECK TIER 1 RESULTS & PREPARE FOR TIER 2 DECISION
// Threshold: 80% of target = Tier 1 success
// Handles 0 results from alwaysOutputData (empty item)

const inputData = $('Build Tier 1 Input').first().json;
const tier1Results = $input.all();

// Extract profiles from Apify response - handles empty items from alwaysOutputData
let tier1Profiles = [];
for (const item of tier1Results) {
  const j = item.json || {};
  if (j.dataset && j.dataset.items) {
    tier1Profiles.push(...j.dataset.items);
  } else if (j.items) {
    tier1Profiles.push(...j.items);
  } else if (Array.isArray(j)) {
    tier1Profiles.push(...j);
  } else if (j.linkedinUrl) {
    tier1Profiles.push(j);
  }
  // If item is empty {} from alwaysOutputData, no profiles are added (correct)
}

// Deduplicate by LinkedIn URL
const seen = new Set();
