const normalizeString = (str) => {
  if (!str) return '';
  return String(str).toLowerCase().trim();
};

// ============================================================
// STRICT INDUSTRY FILTER - MANDATORY CHECK
// ============================================================

const isIndustryMatch = (candidateIndustry, requiredIndustries, requiredKeywords) => {
  if (!candidateIndustry) return false;

  const candInd = normalizeString(candidateIndustry);

  // Check against required industries
  const industries = (requiredIndustries || []).map(normalizeString);
  for (const reqInd of industries) {
    if (candInd.includes(reqInd) || reqInd.includes(candInd)) {
      return true;
    }
  }

  // Check against required keywords (for industry matching)
  const keywords = (requiredKeywords || []).map(normalizeString);
  for (const kw of keywords) {
    if (candInd.includes(kw)) {
      return true;
    }
  }

  return false;
};

const isExcludedIndustry = (candidateIndustry, excludedIndustries, excludedKeywords) => {
  if (!candidateIndustry) return false;

  const candInd = normalizeString(candidateIndustry);

  // Check excluded industries
  const industries = (excludedIndustries || []).map(normalizeString);
  for (const excInd of industries) {
    if (candInd.includes(excInd)) {
      return true;
    }
  }

  // Check excluded keywords
  const keywords = (excludedKeywords || []).map(normalizeString);
  for (const kw of keywords) {
    if (candInd.includes(kw)) {
      return true;
    }
  }

  return false;
};

const hasTitleKeywordMatch = (candidateTitle, requiredKeywords) => {
  if (!candidateTitle || !requiredKeywords?.length) return true; // No filter if no keywords

  const titleLower = normalizeString(candidateTitle);
  const keywords = requiredKeywords.map(normalizeString);

  // At least one keyword must be in title
  return keywords.some(kw => titleLower.includes(kw));
};

// ============================================================
// STRICT FILTER FUNCTION - APPLIED BEFORE SCORING
// ============================================================

const strictFilter = (candidate) => {
  const requiredIndustries = mandatorySignals.industries || [];
  const requiredKeywords = mandatorySignals.keywords || [];
  const excludedIndustries = excludedSignals.industries || [];
  const excludedKeywords = excludedSignals.keywords || [];

  // Get candidate's industry
  const candidateIndustry = candidate.industry ||
                           candidate.currentCompanyIndustry ||
                           candidate.current_company_industry || '';

  // Get candidate's title
  const candidateTitle = candidate.currentTitle ||
                        candidate.current_title ||
                        candidate.headline || '';

  // RULE 1: If we have required industries, candidate MUST match
  if (requiredIndustries.length > 0) {
    const industryMatch = isIndustryMatch(candidateIndustry, requiredIndustries, requiredKeywords);

    // If industry field is empty, check title for industry keywords
    if (!candidateIndustry) {
      const titleHasIndustry = requiredKeywords.some(kw =>
        normalizeString(candidateTitle).includes(normalizeString(kw))
      );
      if (!titleHasIndustry) {
        return { pass: false, reason: 'no_industry_match' };
      }
    } else if (!industryMatch) {
      return { pass: false, reason: 'industry_mismatch' };
    }
  }

  // RULE 2: Check excluded industries
  if (excludedIndustries.length > 0) {
    if (isExcludedIndustry(candidateIndustry, excludedIndustries, excludedKeywords)) {
      return { pass: false, reason: 'excluded_industry' };
    }
  }

  // RULE 3: Title must have some relevance (at least one keyword match)
  if (requiredKeywords.length >= 3) {
    const hasRelevantTitle = hasTitleKeywordMatch(candidateTitle, requiredKeywords.slice(0, 5));
    if (!hasRelevantTitle) {
      return { pass: false, reason: 'no_title_relevance' };
    }
  }

  return { pass: true, reason: 'passed' };
};

// ============================================================
// SCORING FUNCTIONS
// ============================================================

const calculateTitleSimilarity = (profileTitle, anchorTitle, mandatoryTitles) => {
  if (!profileTitle) return 0;
  const pTitle = normalizeString(profileTitle);
  const aTitle = normalizeString(anchorTitle);

  let score = 0;

  // Exact match with anchor
  if (pTitle === aTitle) {
    score += 30;
  }
  // Partial match with anchor
  else if (pTitle.includes(aTitle) || aTitle.includes(pTitle)) {
    score += 20;
  }
  // Word overlap with anchor
  else {
    const pWords = new Set(pTitle.split(/\s+/));
    const aWords = new Set(aTitle.split(/\s+/));
    const overlap = [...pWords].filter(w => aWords.has(w) && w.length > 2).length;
    score += Math.min(overlap * 5, 15);
  }

  // Check mandatory titles
  const titles = mandatoryTitles || [];
  for (const t of titles) {
    if (pTitle.includes(normalizeString(t))) {
      score += 10;
      break;
    }
  }

  return score;
};

const calculateIndustrySimilarity = (profileIndustry, anchorIndustries, mandatoryIndustries) => {
  if (!profileIndustry) return 0;
  const pInd = normalizeString(profileIndustry);

  let score = 0;

  // Check anchor industries - INCREASED WEIGHT
  const aIndustries = (anchorIndustries || []).map(normalizeString);
  for (const aInd of aIndustries) {
    if (pInd === aInd) {
      score += WEIGHTS.INDUSTRY_MATCH;
      break;
    } else if (pInd.includes(aInd) || aInd.includes(pInd)) {
      score += WEIGHTS.TITLE_MATCH;
      break;
    }
  }

  // Check mandatory industries - INCREASED WEIGHT
  const mIndustries = (mandatoryIndustries || []).map(normalizeString);
  for (const mInd of mIndustries) {
    if (pInd.includes(mInd)) {
      score += 20;  // INCREASED from 5
      break;
    }
  }

  return score;
};

const calculateExperienceScore = (yearsExperience) => {
  const years = parseInt(yearsExperience) || 0;
  if (years >= 15) return 10;  // REDUCED from 15
  if (years >= 10) return 8;
  if (years >= 7) return 6;
  if (years >= 5) return 5;
  if (years >= 3) return 3;
  return 2;
};

const calculateSeniorityScore = (seniorityLevel) => {
  const level = normalizeString(seniorityLevel);
  if (level.includes('executive') || level.includes('c-level') || level.includes('chief')) return 10;
  if (level.includes('director') || level.includes('vp') || level.includes('head')) return 8;
  if (level.includes('senior') || level.includes('manager')) return 6;
  if (level.includes('mid') || level.includes('lead')) return 4;
  return 2;
};

const calculateTierBonus = (tier) => {
  // Tier 1 profiles get highest priority
  if (tier === 1) return 15;  // REDUCED from 20
  if (tier === 2) return 8;
  return 0;
};

