const tiersExecuted = inputData.tiers_executed || 1;
const scoringStats = inputData.scoring_stats || {};

// PREPARE CANDIDATE PROFILES FOR BULK INSERT
const candidateProfiles = scoredProfiles.map(profile => {
  const name = profile.fullName || `${profile.firstName || ''} ${profile.lastName || ''}`.trim() || profile.name || 'Unknown';
  const linkedinUrl = profile.linkedinUrl || profile.linkedin_url || '';
  const score = profile._similarity_score || 0;
  let matchQuality = 'weak';
  if (score >= 80) matchQuality = 'excellent';
  else if (score >= 65) matchQuality = 'strong';
  else if (score >= 50) matchQuality = 'good';
  else if (score >= 35) matchQuality = 'moderate';

  return {
    session_id: sessionId,
    linkedin_url: linkedinUrl,
    name: name,
    photo_url: profile.profilePicture || profile.photo_url || profile.photoUrl || null,
    headline: profile.headline || profile.tagline || null,
    current_title: profile.currentTitle || profile.position || profile.headline?.split(' at ')[0] || null,
    current_company: profile.companyName || profile.currentCompany || profile.currentPosition?.[0]?.companyName || profile.headline?.split(' at ')[1] || null,
    location: typeof profile.location === 'object'
      ? (profile.location?.parsed?.text || profile.location?.linkedinText || JSON.stringify(profile.location))
      : (profile.location || null),
    seniority_level: profile.seniorityLevel || null,
    years_experience: parseInt(profile.yearsOfExperience) || 0,
    top_skills: JSON.stringify(profile.skills || profile.topSkills || []),
    education: JSON.stringify(profile.education || profile.educations || []),
    work_history: JSON.stringify(profile.positions || profile.workHistory || profile.experience || []),
    profile_completeness: profile.profileCompleteness || 0,
    similarity_score: score,
    match_quality: matchQuality,
    match_reasons: JSON.stringify(profile._score_breakdown || {}),
    profile_data: JSON.stringify(profile),
    // FIX: Add metadata fields that were missing
    tier_source: profile._tier || null,
    scrape_run_id: sessionId,
    batch_number: 1
  };
}).filter(p => p.linkedin_url && p.name !== 'Unknown');

// PREPARE CANDIDATE PREVIEW (Top 20 for response)
const candidatePreview = scoredProfiles.slice(0, 20).map(profile => ({
  name: profile.fullName || `${profile.firstName || ''} ${profile.lastName || ''}`.trim() || profile.name || 'Unknown',
  title: profile.headline || profile.currentTitle || profile.occupation || '',
  company: profile.companyName || profile.currentCompany || profile.currentPosition?.[0]?.companyName || '',
  location: profile.location?.parsed?.text || profile.location?.linkedinText || profile.location || '',
  linkedin_url: profile.linkedinUrl || profile.linkedin_url || '',
  photo_url: profile.profilePicture || profile.photo_url || '',
  similarity_score: profile._similarity_score,
  score_breakdown: profile._score_breakdown,
  tier: profile._tier,
  seniority: profile.seniorityLevel || '',
  experience_years: profile.yearsOfExperience || 0
})).filter(c => c.name && c.name !== 'Unknown');

const strongMatchesCount = candidateProfiles.filter(p => p.match_quality === 'excellent' || p.match_quality === 'strong').length;

return [{
  json: {
    session_id: sessionId,
    profile_name: inputData.profile_name,
    role_family: inputData.role_family,
    lookalike_results: JSON.stringify(candidateProfiles.slice(0, 100)),
    results_count: candidateProfiles.length,
    strong_matches_count: strongMatchesCount,
    candidate_profiles: candidateProfiles,
    profiles_to_save: candidateProfiles.length,
    response_data: {
      success: true,
      message: `3-Tier Progressive Search completed. Found ${scoredProfiles.length} of ${targetCount} requested profiles.`,
      data: {
        session_id: sessionId,
        profile_name: inputData.profile_name,
        step: 4,
        status: 'completed',
        role_family: inputData.role_family,
        total_results: candidateProfiles.length,
        target_results: targetCount,
        target_met: targetMet,
        tiers_executed: tiersExecuted,
        profiles_saved: candidateProfiles.length,
        strong_matches: strongMatchesCount,
        average_score: scoringStats.avg_score || 0,
        search_results: {
          total_qualified: candidateProfiles.length,
          quality_breakdown: scoringStats.quality_breakdown,
          tier_distribution: scoringStats.tier_distribution,
          avg_similarity_score: scoringStats.avg_score,
          candidates_preview: candidatePreview
        },
        tier_summary: inputData.tier_results,
        lookalike_anchor: inputData.lookalike_anchor ? {
          title: inputData.lookalike_anchor.currentTitle,
          company: inputData.lookalike_anchor.currentCompany,
          seniority: inputData.lookalike_anchor.seniorityLevel,
          industries: inputData.lookalike_anchor.industries
        } : null,
        firmographic_constraints: inputData.firmographic_constraints,
        enforced_mandatory_signals: inputData.enforced_mandatory_signals
      },
      errors: []
    }
  }
}];

// ============================================================
// FORMAT RESULTS RESPONSE
// Query candidate_profiles and format for API response
// ============================================================

const profiles = $input.all().map(item => item.json);

// Parse JSON fields if stored as strings
const formattedProfiles = profiles.map(p => ({
  id: p.id,
  name: p.name,
  photo_url: p.photo_url,
  headline: p.headline,
  current_title: p.current_title,
  current_company: p.current_company,
  location: p.location,
  seniority_level: p.seniority_level,
  years_experience: p.years_experience,
  similarity_score: p.similarity_score,
  match_quality: p.match_quality,
  linkedin_url: p.linkedin_url,
  top_skills: typeof p.top_skills === 'string' ? JSON.parse(p.top_skills || '[]') : (p.top_skills || []),
  education: typeof p.education === 'string' ? JSON.parse(p.education || '[]') : (p.education || []),
  work_history: typeof p.work_history === 'string' ? JSON.parse(p.work_history || '[]') : (p.work_history || []),
  created_at: p.created_at
}));

// Sort by similarity score descending
formattedProfiles.sort((a, b) => (b.similarity_score || 0) - (a.similarity_score || 0));

return [{
  json: {
    success: true,
    message: `Retrieved ${formattedProfiles.length} candidate profiles`,
    data: {
      results: formattedProfiles,
      total_count: formattedProfiles.length,
      strong_matches: formattedProfiles.filter(p => p.match_quality === 'strong').length,
      good_matches: formattedProfiles.filter(p => p.match_quality === 'good').length
    }
  }
}];

// ============================================================
// FORMAT STATUS RESPONSE
// Return session scrape status
// ============================================================

const session = $input.first().json;

const statusMap = {
  'pending': 'Waiting to start',
  'in_progress': 'Scraping in progress',
  'completed': 'Scraping completed',
  'failed': 'Scraping failed'
};

return [{
  json: {
    success: true,
    message: statusMap[session.scrape_status] || statusMap[session.status] || 'Unknown status',
    data: {
      session_id: session.session_id,
      status: session.status,
      scrape_status: session.scrape_status || session.status,
      current_phase: session.current_phase,
      current_step: session.current_step,
      results_count: session.results_count || 0,
      strong_matches_count: session.strong_matches_count || 0,
      target_results_count: session.target_results_count || 50,
      progress_percent: session.results_count && session.target_results_count 
        ? Math.min(100, Math.round((session.results_count / session.target_results_count) * 100)) 
        : 0,
      created_at: session.created_at,
      updated_at: session.updated_at
    }
  }
}];

// ============================================================
// SPLIT CANDIDATE PROFILES FOR BULK INSERT
// Output each profile as individual item for Supabase insert
// ============================================================

const inputData = $('Save Lookalike Results').first().json;
const profiles = inputData.candidate_profiles || [];

if (profiles.length === 0) {
  return [{ json: { skip: true, message: 'No profiles to insert' } }];
}

// Return each profile as a separate item
return profiles.map(profile => ({
  json: {
    ...profile,
    // Pass through session data for later nodes
    _session_id: inputData.session_id,
    _results_count: inputData.results_count,
    _strong_matches_count: inputData.strong_matches_count
  }
}));

// ============================================================
// COLLECT INSERT RESULTS
// Aggregate profile insert results and prepare for session update
// ============================================================

const allResults = $input.all();
let insertedCount = 0;
let failedCount = 0;
let sessionId = '';
let resultsCount = 0;
let strongMatchesCount = 0;

for (const item of allResults) {
  const json = item.json;

  // Track session data from first item
  if (!sessionId && json._session_id) {
    sessionId = json._session_id;
    resultsCount = json._results_count || 0;
    strongMatchesCount = json._strong_matches_count || 0;
  }

  // Check if insert succeeded
  if (json.id) {
    insertedCount++;
  } else if (json.error || json.skip) {
    failedCount++;
  } else {
    // Assume success if no error field
    insertedCount++;
  }
}

// Get data from Save Lookalike Results if not found
if (!sessionId) {
  try {
    const saveResults = $('Save Lookalike Results').first().json;
    sessionId = saveResults.session_id;
    resultsCount = saveResults.results_count;
    strongMatchesCount = saveResults.strong_matches_count;
  } catch (e) {
    // Use defaults
    resultsCount = insertedCount;
  }
}

return [{
  json: {
    session_id: sessionId,
    profiles_inserted: insertedCount,
    profiles_failed: failedCount,
    results_count: resultsCount || insertedCount,
    strong_matches_count: strongMatchesCount,
    insert_summary: {
      total_attempted: allResults.length,
      successful: insertedCount,
      failed: failedCount
    }
  }
}];

const body = $input.first().json;

if (!body.linkedin_url) {
  throw new Error('linkedin_url is required for email reveal');
}
if (!body.profile_id) {
  throw new Error('profile_id is required for email reveal');
}
if (!body.linkedin_url.includes('linkedin.com')) {
  throw new Error('Invalid LinkedIn URL format');
}

return [{
  json: {
    linkedin_url: body.linkedin_url,
    profile_id: body.profile_id,
    session_id: body.session_id || null
  }
}];

const result = $input.first().json;
const profileId = $('Validate Email Request').first().json.profile_id;
const sessionId = $('Validate Email Request').first().json.session_id;

const email = result.contact_info?.email
  || result.personal_emails?.[0]
  || result.email
  || result.emails?.[0]
  || null;

const confidence = result.contact_info?.has_email ? 'high' : (email ? 'medium' : 'none');
const source = 'apify_linkedin_detail';

if (!email) {
  return [{
    json: {
      success: false,
      profile_id: profileId,
      session_id: sessionId,
      email: null,
      confidence: 'none',
      source: source,
      email_found_at: null,
      error: 'Email not found for this LinkedIn profile'
    }
  }];
}

return [{
  json: {
    success: true,
    profile_id: profileId,
    session_id: sessionId,
    email: email,
    confidence: confidence,
    source: source,
    email_found_at: new Date().toISOString(),
    full_name: result.basic_info?.fullname || null
  }
}];

const emailData = $('Parse Email Result').first().json;

return [{
  json: {
    success: emailData.success,
    profile_id: emailData.profile_id,
    email: emailData.email || null,
    confidence: emailData.confidence || 'none',
    source: emailData.source || 'unknown',
    error: emailData.error || null
  }
}];
